        "example": "t3template.addControl({ id: 'punch', label: 'Punch', type: 'slider', min: 0, max: 100, step: 1, default: 40, panel: 'Finish' });\nt3template.addControl({ id: 'fades', label: 'Clip Fades s', type: 'slider', min: 0, max: 2, step: 0.1, default: 0, panel: 'Finish' });\nt3template.addControl({ id: 'title', label: 'Title', type: 'text', default: 'Sonoma', panel: 'Finish' });\nt3template.addControl({ id: 'titleSec', label: 'Title (s)', type: 'slider', min: 0, max: 6, step: 0.5, default: 2.5, panel: 'Finish' });\nt3template.addControl({ id: 'lowcut', label: 'Low Cut Hz', type: 'slider', min: 20, max: 300, step: 5, default: 80, panel: 'Finish' });\n// Sound: heard while the monitor plays and rendered by ffmpeg on the mixed track.\nt3template.addAudioFilter('lowcut', (c) => ({ type: 'highpass', frequency: c.lowcut }));\nconst look = (c) => t3template.grade({ contrast: c.punch * 0.3, saturation: c.punch * 0.5 });\n// Fade each clip in and out: the preview dims near clip edges, the export uses ffmpeg fade with timeline enable.\nt3template.addPreviewFilter((c, { time, clip }) => {\n  if (!clip || !c.fades) return look(c).css;\n  const edge = Math.min(time - clip.start, clip.start + clip.duration - time);\n  return `${look(c).css} brightness(${Math.min(1, Math.max(0, edge / c.fades)).toFixed(3)})`;\n});\nt3template.addExportNote((edl, c) => {\n  const fades = c.fades ? edl.tracks[0].clips.flatMap((k) => {\n    const end = k.start + k.duration;\n    return [`fade=t=in:st=${k.start}:d=${c.fades}:enable='between(t,${k.start},${k.start + c.fades})'`,\n      `fade=t=out:st=${end - c.fades}:d=${c.fades}:enable='between(t,${end - c.fades},${end})'`];\n  }) : [];\n  return { videoFilter: [look(c).ffmpeg, ...fades].filter(Boolean).join(','), note: `Finish: punch ${c.punch}, clip fades ${c.fades} s` };\n});\n// Title card: drawn once at the picture size, shown over the first titleSec seconds on the monitor and in the render.\nt3template.addOverlay('title', ({ context, width, height }, c) => {\n  context.fillStyle = 'rgba(0, 0, 0, 0.55)';\n  context.fillRect(0, height * 0.4, width, height * 0.2);\n  context.fillStyle = '#ffffff';\n  context.font = `600 ${Math.round(height * 0.09)}px sans-serif`;\n  context.textAlign = 'center';\n  context.textBaseline = 'middle';\n  context.fillText(c.title, width / 2, height / 2);\n}, (c) => (c.title && c.titleSec ? { start: 0, end: c.titleSec } : null));\nt3template.addToolbarButton('Mark Beat', (t) => {\n  const v = t.getValues();\n  t.setValues({ markers: [...v.markers, { time: v.playhead, label: 'Beat' }] }, 'Mark Beat');\n}, { shortcut: 'b' });"
